input.sparql:
SELECT ?z ?type ?label ?ts ?point WHERE {
  ?z a brick:Zone .
  OPTIONAL { ?z rdfs:label ?label }
  OPTIONAL { ?p ref:hasTimeseriesId ?ts ; brick:hasProperty [brick:isA brick:Zone_Temperature] . }
}

SELECT ?point ?ts ?class ?unit WHERE {
  ?point brick:isPointOf ?z .
  ?z a brick:Zone .
  OPTIONAL { ?point ref:hasExternalReference ?r ; ref:hasTimeseriesId ?ts }
  OPTIONAL { ?point brick:isA ?class }
  OPTIONAL { ?point brick:hasUnit ?unit }
  FILTER(CONTAINS(STR(?point), "Zone_F3_Z01"))
}

SELECT ?point ?refid ?class WHERE {
  ?point ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?refid .
  OPTIONAL { ?point brick:isA ?class }
  FILTER(CONTAINS(STR(?point), "Zone_F3_Z01"))
}

SELECT ?point ?ts ?class WHERE {
  ?point ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?ts .
  ?point a ?class .
  FILTER(CONTAINS(STR(?point), "Zone_") && CONTAINS(STR(?point), "Zone_Air_Temperature_Sensor"))
}

SELECT DISTINCT ?room WHERE {
  ?z a brick:Zone .
  ?z brick:hasPart ?room .
  FILTER (CONTAINS(STR(?z), "Zone_F3_Z01"))
}

SELECT ?pt ?ts WHERE {
  ?pt ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?ts .
  ?pt a ?cls .
  FILTER (CONTAINS(STR(?pt), "Zone_F3_Z01"))
}

SELECT ?pt ?ts WHERE {
  ?pt ref:hasExternalReference ?ref .
  ?ref ref:hasTimeseriesId ?ts .
  ?pt a ?cls .
  FILTER (CONTAINS(STR(?pt), "VAV_F3_Z01") )
}
